found=[]
def walk(o,path=''):
    if isinstance(o,dict):
        for k,v in o.items():
            if k=='raffles' and isinstance(v,list):
                for r in v:
                    if isinstance(r,dict):
                        found.append((path,r))
            else: walk(v,path+'/'+k)
    elif isinstance(o,list):
        for i,v in enumerate(o): walk(v,path+f'[{i}]')
walk(d)
